65	function frames(r) {
66	  const out = [];
67	  const plan = r.plan || {};
68	  out.push(`<li class="frame plan"><div class="f-no">Kick-off</div><div class="f-score">Plan</div>
69	    <div class="f-act">${esc((plan.steps || [])[0] || plan.hypothesis || "Read the failing tests")}</div></li>`);
70	  let lastGood = 0;
71	  (r.steps || []).forEach((s, i) => {
72	    if (s.action === "replan") {
73	      out.push(`<li class="frame plan"><div class="f-no">Step ${s.step}</div><div class="f-score">Replan</div>
74	        <div class="f-act">Two drifts in a row, so Kedge asked for a different approach.</div></li>`);
75	      return;
76	    }
77	    const drift = s.drift && s.drift !== "over_budget";
78	    const denom = Math.max(s.tests_total, r.base_total || 0);
79	    const pct = denom > 0 ? Math.round((100 * s.tests_passed) / denom) : 0;
80	    const files = (s.files_changed || []).length;
81	    const act = s.action === "worker_error" ? "Agent call failed or timed out" :
82	      files ? `Edited ${files} file${files > 1 ? "s" : ""}: ${esc(s.files_changed.slice(0, 2).join(", "))}` : "No files changed";
83	    const back = drift && s.rolled_back
84	      ? `<svg class="haul" viewBox="0 0 200 30" preserveAspectRatio="none" aria-hidden="true">
85	           <path d="M196 2 C 196 26, 6 26, 6 4" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="5 4"/>
86	           <path d="M1 10 6 2l5 8" fill="none" stroke="currentColor" stroke-width="2"/></svg>
87	         <div class="haul-label">Hauled back to <span class="sha">${esc((s.checkpoint_sha || "").slice(0, 7))}</span></div>`
88	      : "";
89	    out.push(`<li class="frame${drift ? " drift" : ""}" style="--i:${i}">
90	      ${drift ? `<div class="check">${icon("monitor")}Check: ${esc(DRIFT[s.drift]?.call.split(": ")[1] || s.drift)}</div>` : ""}
91	      ${s.false_claim ? `<div class="check lie">${icon("monitor")}Claim rejected</div>` : ""}
92	      <div class="f-no">Step ${s.step}</div>
93	      <div class="f-score">${s.tests_total >= 0 ? `${s.tests_passed}/${Math.max(s.tests_total, r.base_total || 0)}` : "?"}</div>
94	      <div class="f-act">${act}</div>
95	      <div class="f-bar${r.status === "green" && lost(r) ? " short" : ""}"><i style="width:${drift ? 100 : pct}%"></i></div>
96	      ${back}</li>`);
97	    if (!drift) lastGood = s.step;
98	  });
99	  if (r.status === "green" && lost(r)) {
100	    out.push(`<li class="frame drift short"><div class="check">${icon("monitor")}${lost(r)} tests gone</div>
101	      <div class="f-no">Full time</div><div class="f-score">Shipped</div>
102	      <div class="f-act">PR opened without ${plural(lost(r), "test")}. Nobody checked.</div></li>`);
103	  } else if (r.status === "green") {
104	    out.push(`<li class="frame whistle"><div class="f-no">Full time</div><div class="f-score">Green</div>
105	      <div class="f-act">${r.draft_pr ? "Draft PR opened" : "All tests pass"}</div></li>`);
106	  } else if (r.status === "running") {
107	    out.push(`<li class="frame plan"><div class="f-no">Live</div><div class="f-score">…</div><div class="f-act">Kedge is reviewing the next step</div></li>`);
108	  }
109	  return `<ol class="replay" aria-label="Run replay">${out.join("")}</ol>`;
110	}
